import * as React from "react";

export type CameraReelIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CameraReelIcon({ size = 20, ...props }: CameraReelIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="13" r="6" /><circle cx="12" cy="13" r="2" /><path d="M8 4.5h8" />
    </svg>
  );
}
